[10938] = {id=10938,name="Darkmoon Blessings Deck",level=1,requiredLevel=0,faction="both",expansion=5,zoneID=5861,mapID=407,description="Now that you have gathered all of the Blessings cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",ends={{npcID=14847,x=0.518,y=0.606,mapID=407}},questType="standard"},
[25703] = {id=25703,name="Atrocities",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=4,mapID=17,description="The Bloodwash naga and the Rockpool murloc have lived among one another for as long as we could remember. We have always had our differences, but never provoked one another. Why, then, would they turn on us? Neptool looks over his shoulder at his former villagers.> You see what they do now? They enslave us, sacrifice us, force us to fight one another. I will stop them, ... and you will be my weapon.",starts={{npcID=41354,x=0.71,y=0.598,mapID=17}},ends={{npcID=41354,x=0.71,y=0.598,mapID=17}},coords={x=0.71,y=0.598,source="quest_giver",mapID=17},questType="standard"},
[25707] = {id=25707,name="The Future of the Rockpool",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=4,mapID=17,description="The Rockpool tadpoles left upon this crate appear tired, scared, and nearly dried out. They need to be taken to the water, and quickly. Perhaps if you can drag this crate across the beach and into the Forbidden Sea, far off the coast of the Red Reaches, then they will have a chance of escaping, and the Rockpool murlocs may live on...",questType="standard"},
