[32728] = {id=32728,name="The Court of Bones",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,mapID=504,description="The mogu within the nearby Court of Bones pose a constant threat to our foothold on this island. Grand Magister Rommath has been entrusted with halting their efforts, but I am certain he could use a capable to see this task through. Go to him. Aid in whatever ways that you are able.",starts={{npcID=67673,x=0.324,y=0.352,mapID=504}},ends={{npcID=67989,x=0.384,y=0.512,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="standard"},
[32729] = {id=32729,name="Za'Tual",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,mapID=504,description="The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Halduron Brightwing to take charge of dismantling their presence at Za'Tual, in the south. Report to Halduron when you are best able. He will have work for you.",starts={{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=70371,x=0.284,y=0.522,mapID=504}},ends={{npcID=70520,x=0.368,y=0.648,mapID=504}},coords={x=0.326,y=0.354,source="quest_giver",mapID=504},questType="standard"},
[32731] = {id=32731,name="The Court of Bones",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,description="The mogu within the nearby Court of Bones comprise one of the greatest threats to our presence on this island. Narasi Snowdawn has been entrusted with halting their efforts, but I am certain she could use a capable to see this task through. Go to her. Aid in whatever ways that you are able.",starts={{npcID=67993,x=0.632,y=0.722,mapID=504}},ends={{npcID=67997,x=0.402,y=0.594,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32732] = {id=32732,name="Ihgaluk Crag",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,description="Archmage Modera has taken over at Ihgaluk Crag, to the southeast, continuing her efforts to turn the Saurok against the Zandalari and mogu. Go to her, and help in any way that you can.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67996,x=0.556,y=0.744,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="standard"},
[32733] = {id=32733,name="Za'Tual",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,description="The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Archmage Lan'dalock to take charge of dismantling their presence at Za'Tual, in the south. Report to him when you are best able. He will have work for you.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=70370,x=0.346,y=0.894,mapID=504}},ends={{npcID=70517,x=0.422,y=0.664,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32758] = {id=32758,name="Reader for the Dead Tongue",level=1,requiredLevel=1,faction="none",expansion=5,description="Return to your capital city and seek out a warlock trainer who may know more about the codex.",questType="standard"},
[32803] = {id=32803,name="Treasure: Thunderlord Cache 01",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=220641,x=0.342,y=0.234,mapID=525}},questType="standard"},
[32825] = {id=32825,name="Re-Use Me",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6507,mapID=504,questType="pvp"},
[32826] = {id=32826,name="Re-Use Me",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6507,mapID=504,description="Ah, $p, just the I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Dawnseeker Promontory to the northwest. Here, take these. It is time to give the Sunreavers a taste of their own medicine. Plant one on the Sunreaver ships, another one on their scrying crystals, and the last on the bridge that connects to their forward base.",questType="pvp"},
[32827] = {id=32827,name="Re-Use Me",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6507,mapID=504,description="Even the strongest defense can still have a weakness, . We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible. Scouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly. Disabling them would allow us to keep closer watch on their activities.",questType="pvp"},
[32836] = {id=32836,name="A Knockoff Grumplefloot",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The \"grumplefloot\" has been hastily carved out of a tree root, with holes unevenly spaced along its length. A close inspection of its backside, however, reveals words carved into the wood: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32838] = {id=32838,name="A Tale of Romance and Chivalry",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,description="A small book, written for children. It's well-bound and in fairly good condition. On the back cover of the book, near the spine, you find a few words written in flowing script: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32840] = {id=32840,name="Boom Boom's Fuse",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="Amidst the gibbets of hozen meat and fur flying aimlessly around Kota Kon's sphere of destruction, you seem to have grabbed hold of a small fuse. The fuse is created entirely from woven, matted hozen tail hair. It has a strong smell. Near one of the ends of the fuse, however, is a small paper tag, embossed with the words: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32842] = {id=32842,name="Teeth Like Swords",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=5805,mapID=376,description="The tooth comes to a singular edge, almost as if it were sharpened by stone. It clearly belonged to a ferocious beast. Handling it gingerly, you notice a few tiny words, expertly carved into the enamel: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32844] = {id=32844,name="Secret of the Ooze",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,description="The contents of the vial swirl and froth violently, causing the vessel to tremble in your hand. As you look into the container, you think you catch a fleeting image of a living, angry face. The vial's stopper fits snugly. Around its edge, some small words have been carved with an expert hand: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32846] = {id=32846,name="Modified Chomping Apparatus",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="You might not have recognized this as a modified chomping apparatus if it didn't have the words \" modified chomping apparatus \" messily painted onto it. Right beneath the sloppy label, you see a smaller message, written much more neatly in bright red ink: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32848] = {id=32848,name="Frost-Tipped Eggshell",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="A piece of an eggshell, presumably penguin. Its edges are covered with rime, and based on its curvature, this egg was quite large when it was intact. Strangely, the inside of the eggshell has a message written on it, in jade-green ink: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32850] = {id=32850,name="Last Year's Model",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The robot is in bad shape. It was built with several sockets which, like the Blingtron 4000, presumably once carried gems, but are now empty. The robot's otherwise dust-covered posterior region contains a small, shiny metal plaque, embossed with the words: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32851] = {id=32851,name="Blingtron 3000",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The Blingtron line didn't really pick up until the 4000 series hit the vendor shelves. Few remember the Blingtron 3000, but it was a real engineering marvel in its own right! The challenge card you've unlocked gives you the ability to fight Blingtron 3000 right here, in the Brawler's Guild. Lucky you!",questType="standard"},
[32852] = {id=32852,name="The Digmaster's Earthblade",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="An entirely ordinary-looking shovel. The handle is carved with an ornate script: \"The Digmaster's Earthblade \". On the flipside of the handle, however, is a smaller label, written in simpler text: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32853] = {id=32853,name="Mingus Diggs",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="You've earned the right to challenge Mingus Diggs, the archaeologist! Mingus isn't that tough, from what I hear... but the people in charge let him bring some of his excavated treasures with him into the brawling ring. Those are what you want to watch out for. Come buy his card when you're ready!",questType="standard"},
[32854] = {id=32854,name="Well-Worn Blindfold",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="A piece of cloth, shaped for a human-sized head. The cloth is unadorned and simple, except for a small tag on the end, which reads: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32855] = {id=32855,name="The Blind Hero",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The challenge card you've earned allows you to fight the Blind Hero, a mysterious warrior from a bygone age. Nobody surpasses his skill with a blade. Nobody. Luckily, he can't see anything. Have fun!",questType="standard"},
[32856] = {id=32856,name="Paper-Covered Rock",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="It's a strange combination of items. The paper envelops the rock completely, dwarfing it like a smothering blanket of wood pulp. Compared to the paper, the rock is barely a pebble. When held up to the light, the paper reveals a distinct watermark, along with the text: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32857] = {id=32857,name="Ro-Shambo",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The challenge card you have unlocked will allow you to fight Ro-Shambo, an esoteric creature from parts unknown. Watch out. I hear it's got a few tricks up its sleeve.",questType="standard"},
[32858] = {id=32858,name="Raptorhide Boxing Gloves",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=17,mapID=10,description="The gloves are stitched together roughly, and by the smell of it, they've been treated with crawler mucus. Nevertheless, they appear sturdy and functional. Somewhat unsurprisingly, the inner seam bears the following words: RETURN TO BRAWLER'S GUILD",questType="standard"},
[32863] = {id=32863,name="What We've Been Training For",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5840,mapID=1530,description="Are you ready to put your pets to the test? The battle pet arena is no place for low-level rabbits, you'd better have a rocketbot in your pocket and be ready for action. If you've got three fully-experienced pets, find battles against trainers of similar skill and show the world what you've got. You can find the instructions in your Pet Journal.",starts={{npcID=63596,x=0.692,y=0.25,mapID=84},{npcID=63626,x=0.524,y=0.592,mapID=85},{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},ends={{npcID=63596,x=0.692,y=0.25,mapID=84},{npcID=63626,x=0.524,y=0.592,mapID=85},{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},coords={x=0.692,y=0.25,source="quest_giver",mapID=1530},questType="standard"},
[32868] = {id=32868,name="Beasts of Fable Book II",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6134,mapID=418,description="The stories of Lucky Yi , Greyhoof , and Skitterer Xi'a will exist in this land, always. Do you wish to meet them in battle once more?",starts={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},ends={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},coords={x=0.864,y=0.6,source="quest_giver",mapID=418},questType="standard"},
[32869] = {id=32869,name="Beasts of Fable Book III",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5842,mapID=388,description="The stories of No-No , Ti'un the Wanderer , and Gorespine will exist in this land, always. Do you wish to meet them in battle once more?",starts={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},ends={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},coords={x=0.864,y=0.6,source="quest_giver",mapID=388},questType="standard"},
