[32984] = {id=32984,name="The Ascent",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6720,mapID=525,description="I can feel the voice of the Fury at the top of the ascent. Come, let us climb these stairs together. Be on your guard. The goren of this area are likely to be drawn by the smell of a shaman. If we get separated, fall back to the base of the stairs and regroup.",starts={{npcID=74253,x=0.74,y=0.296,mapID=525}},ends={{npcID=74330,x=0.7,y=0.382,mapID=525}},coords={x=0.74,y=0.296,source="quest_giver",mapID=525},questType="standard"},
