[33138] = {id=33138,name="Why Do We Fight?",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5840,mapID=1530,description="Oh my friend, today you and your companions have put an end to the sha that has plagued Pandaria since before time was recorded. You have accomplished that which even the titans and their mogu servants could not: destroying the last breaths of Y'Shaarj. Come, will you join me in the Vale of Eternal Blossoms? There is something I would like you to bear witness to.",ends={{npcID=73136,x=0.674,y=0.456,mapID=1530}},questType="standard"},
