[33578] = {id=33578,name="Pyrophobia",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="W- we have done n-n-nothing to provoke the arakkoa... w-why would they attack Aruuna? What do they want from us? I want to run, but I'm... too afraid. That leader of theirs will burn me to a crisp, I just know it! H-he's just inside the inn...",starts={{npcID=75311,x=0.776,y=0.44,mapID=535}},ends={{npcID=75311,x=0.776,y=0.44,mapID=535}},coords={x=0.776,y=0.44,source="quest_giver",mapID=535},questType="standard"},
[33579] = {id=33579,name="What the Draenei Found",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="They came here for an artifact? The miners must have found something in our crystal mine to the north. By the Light, can you imagine how powerful that thing must be, to attract them all the way here from their spires? I suppose it is in their hands now... You'd have to be crazy to go looking for it...",starts={{npcID=75311,x=0.776,y=0.44,mapID=535}},ends={{npcID=75469,x=0.826,y=0.378,mapID=535}},coords={x=0.776,y=0.44,source="quest_giver",mapID=535},questType="standard"},
[33580] = {id=33580,name="The Purge of Veil Shadar",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6719,mapID=539,description="Not all arakkoa are alike. It is no illusion. They did this to me. Before I was even given a name, I was given a place in society: at the bottom. We are many. We make our homes in the places this world has forgotten. Veil Shadar was such a place, but the Adherents have found it and started a purge. For morale. For fun. Help my people escape, and we'll be in your debt. When the sky burns, it pays to have allies in the shadows.",starts={{npcID=75288,x=0.704,y=0.568,mapID=535}},ends={{npcID=232592,x=0.553,y=0.748,mapID=539}},coords={x=0.704,y=0.568,source="quest_giver",mapID=539},questType="standard"},
[33581] = {id=33581,name="Forbidden Knowledge",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="Darkscryer Raastok narrows his eyes and looks you up and down.> So, you are Iskar's hired hand? Well, I care not whether you are |5 or an overgrown moth, so long as you are willing to help. The Adherents of Rukhmar are closed-minded fools! They forbid the study of shadow magic, branding as heretics anyone who dares to seek answers in the dark. We kept many tomes of forbidden knowledge in Veil Shadar. Bring any you find to me, and I will reward you for keeping them from the flames.",starts={{npcID=75323,x=0.704,y=0.572,mapID=535}},ends={{npcID=75323,x=0.704,y=0.572,mapID=535}},coords={x=0.704,y=0.572,source="quest_giver",mapID=535},questType="standard"},
[33582] = {id=33582,name="Kura's Vengeance",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="I was a wing-guard myself, once upon a time. One afternoon, I was caught away from my post. I just wanted an hour to watch the festival... Kuuan was supposed to cover for me, but instead he sold me out to gain favor with our superiors. They plucked my eyes, broke my wings, and threw me off the spire. Yet I am the fortunate one, for if Iskar hadn't found me, I'd have died there. And now Kuuan shows his face in Veil Shadar on the same day that you show up willing to kill for coin. Fortunate, indeed.",starts={{npcID=75324,x=0.706,y=0.568,mapID=535}},ends={{npcID=75324,x=0.706,y=0.568,mapID=535}},coords={x=0.706,y=0.568,source="quest_giver",mapID=535},questType="standard"},
[33584] = {id=33584,name="Treasure: Ashes of A'kumbo",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232582,x=0.378,y=0.443,mapID=539}},questType="standard"},
