[33732] = {id=33732,name="Sabotage Siege Weapons",level=20,requiredLevel=20,faction="none",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33734] = {id=33734,name="Pieces of Us",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="When the fires broke out, I took only my daughter's hand before we fled. It was the right decision, of course, but I do long for some of the things we left behind. I am an artificer, a shaper of crystals and gems. Without my tools I am just another refugee. Our town records are kept in a memory crystal in the main hall. With it, I can carry forward the knowledge and legacy of Aruuna. Also, my daughter is terrified - it would be a great comfort for her to hold her favorite doll again.",starts={{npcID=75896,x=0.73,y=0.386,mapID=535}},ends={{npcID=75913,x=0.766,y=0.552,mapID=535}},coords={x=0.73,y=0.386,source="quest_giver",mapID=535},questType="standard"},
[33740] = {id=33740,name="Burning Sky",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="It happened so fast. A white-hot flash of light ignited the nearby woods, followed by terrible winds that swept the flames across Aruuna. Moments later, arakkoa began descending through the smoke. I need to get Melani to the Pilgrim's Road. From there we can head for Anchorite's Sojourn and the protection of the vindicators. With the arakkoa roaming the area freely, I fear we'll be run down or worse: taken by the spreading wildfires.",starts={{npcID=75896,x=0.73,y=0.386,mapID=535}},ends={{npcID=75913,x=0.766,y=0.552,mapID=535}},coords={x=0.73,y=0.386,source="quest_giver",mapID=535},questType="standard"},
[33761] = {id=33761,name="Barum's Notes",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="The most recent pages detail a series of cuts intended to aid the draenei vindicators in battle.> \"...honed to a fine edge, the material can expose weaknesses...\" \"when rounded and polished to such a degree, it wards off harmful...\" \"...this incredible discovery that a crystal can be attuned to the bearer's vitality!\"",starts={{npcID=225778,x=0.763,y=0.427,mapID=535}},ends={{npcID=75913,x=0.766,y=0.552,mapID=535}},coords={x=0.763,y=0.427,source="quest_giver",mapID=535},questType="standard"},
[33782] = {id=33782,name="Keeping the Balance",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Look at these teeth, friend. These stress markings suggest that the crocolisk are being subjugated by one of their own. When a crocolisk female grows large enough, she exerts dominance over her kin. It is my duty as a hunter to ensure balance is restored to these creatures as thanks for their sacrifice for my own life. Track down the beast and slay her while I tend to my wounds. She is likely at the far end of the arbitum.",questType="standard"},
[33839] = {id=33839,name="Tracking Quest: Saw Naaru Purified",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33843] = {id=33843,name="Vignette: Broodmother Reeg'ak",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,description="Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us. Fortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster. If we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent.",questType="standard"},
