[34063] = {id=34063,name="Enemies Above",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="We have dealt a crushing blow to the Thunderlords with the death of the Iron Wolf , but we can not rest yet. The Thunderlord generals will be fighting like caged wolves to maintain their place in the Iron Horde and that means bad news for us. I sent Scout Ruk'gan to keep an eye on their movements but he hasn't reported back for some time now. If you would help us then seek out Ruk'gan. Lok'tar !",questType="standard"},
[34068] = {id=34068,name="Vignette: Rockhoof",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[34077] = {id=34077,name="Trouble to the South",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="A group of Alliance soldiers headed south from here not long ago. They said they were searching for some sort of special flower. To be frank, I'm concerned for their safety. This area is still crawling with Iron Horde. They could surely use your help if you're able. Follow the road south and you should find their position.",questType="standard"},
[34079] = {id=34079,name="Mission Successful",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The Thunderlords are finished and our job is complete. I'll stay here and watch over the area. You should head back to Sergeant Gil'nath. I'm certain he will have another task for you.",questType="standard"},
