[34653] = {id=34653,name="Arakkoa Exodus",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="I assume you're familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial. Some, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside. It seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves. We should make contact with these outcasts - they could have valuable information.",starts={{npcID=78487,x=0.456,y=0.432,mapID=525},{npcID=81492,x=0.378,y=0.368,mapID=539}},ends={{npcID=79539,x=0.378,y=0.18,mapID=542}},coords={x=0.456,y=0.432,source="quest_giver",mapID=542},questType="standard"},
