[34685] = {id=34685,name="As the Smoke Rises",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="Aruuna burns. The arakkoa swooped down from their spires and are turning everything to ash. Draenei, talbuk, even orc; they care not for allegiances. They merely want to watch the world burn. I barely escaped with my life, but my best friend, Barum, stayed behind to find his daughter. The others all say you are a great champion. Please, I beg of you, go to Aruuna and find them.",starts={{npcID=79573,x=0.694,y=0.214,mapID=535}},ends={{npcID=75896,x=0.73,y=0.386,mapID=535}},coords={x=0.694,y=0.214,source="quest_giver",mapID=535},questType="standard"},
[34688] = {id=34688,name="DEPRECATED",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[34691] = {id=34691,name="Just the Beginning",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,description="I forgive Orgrim. He acted as well all must - we do what our hearts tell us is right. We should return to your outpost and discuss our next course of action. There is nothing left for us here. I will ask the human to open a portal for us. We shall speak again there.",questType="standard"},
