[34765] = {id=34765,name="The Den of Skog",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="So this gronn infestation ain't gonna solve itself. You're gonna have to show them who's boss, Horde style! With this many gronnlings around there is bound to be a full grown, big mama of a gronn. Find him... it... her... or whatever, and take it out, and the rest of those gronnlings might lose interest in our little operation here.",starts={{npcID=78466,x=0.488,y=0.65,mapID=525},{npcID=78466,x=0.42,y=0.55,mapID=525}},ends={{npcID=78466,x=0.488,y=0.65,mapID=525},{npcID=78466,x=0.42,y=0.55,mapID=525}},coords={x=0.488,y=0.65,source="quest_giver",mapID=525},questType="standard"},
