[34836] = {id=34836,name="Lunarblossom",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="How I long to hold Kat'la. No star or moon can compare to her beauty. Alas, I am but a simple boar farmer. If only I could find time to sneak away from this pathetic excuse for a job and pick some lunarblossoms for Kat'la. I wouldn't dare confess my love to her without a gift.",starts={{npcID=80248,x=0.464,y=0.252,mapID=539}},ends={{npcID=80248,x=0.464,y=0.252,mapID=539}},coords={x=0.464,y=0.252,source="quest_giver",mapID=539},questType="standard"},
