[34847] = {id=34847,name="Forbidden Love",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="My son, Kral'za, is beyond stubborn. After we split from the Shadowmoon Clan he refused to let go of his relationship with a young Shadowmoon orc. I forbid him to see her anymore. He ran off earlier today and has not returned. I don't trust Dol'mak . Like the other Shadowmoon orcs she continues to dabble in the void.",starts={{npcID=77211,x=0.46,y=0.254,mapID=539}},ends={{npcID=77211,x=0.46,y=0.254,mapID=539}},coords={x=0.46,y=0.254,source="quest_giver",mapID=539},questType="standard"},
