[35750] = {id=35750,name="Lunatic Lieutenants",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,mapID=17,description="It is time we learned more about our new enemy. Our scouts have identified a number of the Iron Horde's lieutenants. Their attack is too organized to be run by tribal knowledge alone. Surely their lieutenants have access to secret battleplans. You are the only soldier I can trust with this mission, .",starts={{npcID=84928,x=0.486,y=0.318,mapID=17}},ends={{npcID=84928,x=0.486,y=0.318,mapID=17}},coords={x=0.486,y=0.318,source="quest_giver",mapID=17},questType="standard"},
