[35828] = {id=35828,name="I Drew Aggro...culture",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="$p? Boy am I glad to see ya. I was tryin' ta ditch that genesaur when I stumbled across this rangari camp. Next thing I know, the ground is creepin' up and spittin' out all sorts of angry plants. I barely made it out of me tank before that genesaur threw it like it was an empty beer mug. I'm gonna make my way back to the road an' look fer me tank. I'll see ya there when yer done.",starts={{npcID=80874,x=0.65,y=0.486,mapID=543}},ends={{npcID=75136,x=0.632,y=0.524,mapID=543}},coords={x=0.65,y=0.486,source="quest_giver",mapID=543},questType="standard"},
