[35878] = {id=35878,name="Safety Measures",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,mapID=542,description="As it turns out, the resonance frequency of the batteries has really upset the local wildlife. I... I think one of the boars looked at me and licked its lips just a moment ago. I'll make it worth your time if you just... get rid of anything you come across down there. Doesn't matter what it is, just kill it, okay?",starts={{npcID=82759,x=0.562,y=0.424,mapID=542}},ends={{npcID=82759,x=0.562,y=0.424,mapID=542}},coords={x=0.562,y=0.424,source="quest_giver",mapID=542},questType="standard"},
