[36385] = {id=36385,name="Legacy of the Ancients",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=6755,mapID=550,description="Opening the ancient tome you see that it's not actually a tome at all, but a container. Inside are four empty slots. Upon closer inspection each slot has next to it a carving of what appears to be a unique Draenor ancient, some glyphs and a receptacle used to hold a piece of the pictured ancient. There also appear to be directions to where these ancients may be found: medium timber -- Shadowmoon, Gorgrond, the Spires of Arak and Nagrand. These are assassination instructions. From trees to kill trees.",ends={{npcID=84247,x=0.518,y=0.61,mapID=525},{npcID=84248,x=0.348,y=0.496,mapID=539}},questType="standard"},
