[37784] = {id=37784,name="Shadowmoon Burial Grounds",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6932,description="Ner'zhul was once a noble orc - he was the wise chieftain and elder shaman of the Shadowmoon clan. In his desperate bid to join the Iron Horde he has spat on all he once stood for and twisted his ancestors' spirits to tap into dark, forbidden power... all to please Hellscream. The Shadowmoon has fallen, commander. Enter their ancestral burial grounds and put an end to Ner'zhul 's madness before he pulls all of Draenor into the engulfing maw of the void.",starts={{npcID=89753,x=0.402,y=0.56,mapID=525},{npcID=91195,x=0.402,y=0.56,mapID=525}},ends={{npcID=78487,x=0.456,y=0.432,mapID=525}},coords={x=0.402,y=0.56,source="quest_giver",zoneID=7004},questType="dungeon"},
[37792] = {id=37792,name="Shadowmoon Burial Grounds",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6932,description="Ner'zhul wasn't always evil - once he was the wise chieftain and elder shaman o' the Shadowmoon clan. In his desperate bid to join the Iron Horde he's forsaken all he once stood for and twisted his ancestors' spirits to tap into dark, forbidden power... all to please Hellscream. Enter their ancestral burial grounds and put an end to Ner'zhul 's madness before he pulls all o' Draenor into the engulfing maw o' the void.",starts={{npcID=89763,x=0.344,y=0.33,mapID=539},{npcID=91196,x=0.344,y=0.33,mapID=539}},ends={{npcID=81492,x=0.378,y=0.368,mapID=539}},coords={x=0.344,y=0.33,source="quest_giver",zoneID=7078},questType="dungeon"},
