[38176] = {id=38176,name="Missive: Assault on Stonefury Cliffs",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines. Shadow Hunter Rokhan has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38177] = {id=38177,name="Missive: Assault on Magnarok",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north. If we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38178] = {id=38178,name="Missive: Assault on the Iron Siegeworks",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge. A strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38179] = {id=38179,name="Missive: Assault on the Everbloom Wilds",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place. Rokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38180] = {id=38180,name="Missive: Assault on the Broken Precipice",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them. Most of these ogron appear to be coming from the Broken Precipice , deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38181] = {id=38181,name="Missive: Assault on Mok'gol Watchpost",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen. If we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38182] = {id=38182,name="Missive: Assault on Darktide Roost",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts. The most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38183] = {id=38183,name="Missive: Assault on Socrethar's Rise",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley. Socrethar's disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38184] = {id=38184,name="Missive: Assault on Lost Veil Anzu",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu. Rokhan has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38185] = {id=38185,name="Missive: Assault on Pillars of Fate",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak. Rokhan is concerned at their proximity to key choke points leading into Shadowmoon Valley, and has put out a request that we thin their forces as soon as possible.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38186] = {id=38186,name="Missive: Assault on Skettis",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads. Guards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38187] = {id=38187,name="Missive: Assault on Shattrath Harbor",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar. The Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.",ends={{npcID=78495,x=0.408,y=0.518,mapID=525}},questType="standard"},
[38194] = {id=38194,name="Missive: Assault on the Gorian Proving Grounds",level=40,requiredLevel=40,faction="none",expansion=5,description="The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand. A decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.",questType="standard"},
[38202] = {id=38202,name="Missive: Assault on the Gorian Proving Grounds",level=40,requiredLevel=40,faction="none",expansion=5,description="The ogres at the Gorian Proving Grounds be rousin' champions to turn against our forces in Nagrand. A decisive assault on their training grounds should prevent dem from musterin' the forces dey be needin' to stand against us, and will help remind them that we are not an enemy they want to be makin'.",questType="standard"},
[38207] = {id=38207,name="Vignette: Zeter'el",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6723,mapID=534,questType="standard"},
