[38219] = {id=38219,name="Defending The Grove",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="The harpies have had a presence in Val'Sharah for hundreds of years. They have never been much more than an occasional nuisance; thus we have tolerated their presence here within these woods. However, something has emboldened them... it feels as though the forest is weakening... they must sense it as well. The opportunistic harpies have broken the peace and attacked us in a time of weakness. Help us defend Thas'talah by slaying the invaders.",questType="standard"},
[38220] = {id=38220,name="Arauk Nashal 70:JP3 - Aggramar's Vault - Tracking Quest Cleared - Aggramar's Vault",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38277] = {id=38277,name="Treasure: Honey Hive",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38278] = {id=38278,name="Vignette: Kraw the Mystic",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38282] = {id=38282,name="Vignette: Wakkawam",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38285] = {id=38285,name="Menacing Sprites",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="The local sprites are running amok and causing all sorts of problems! Val'sharah is home to a variety of forest and pond sprites will take any opportunity to spread mischief and chaos. It seems as though an especially wicked group of sprites have descended upon Thas'talah in the wake of the harpy invasion. They are attacking the local wildlife and bullying the nearby faerie dragons. If you aid the local woodland creatures by taking care of the sprite menace, you will have our thanks.",questType="standard"},
[38288] = {id=38288,name="Raw Beast Hides",level=10,requiredLevel=10,faction="none",expansion=5,questType="standard"},
[38294] = {id=38294,name="Sumptuous Fur",level=10,requiredLevel=10,faction="none",expansion=5,questType="standard"},
[38297] = {id=38297,name="Herbs Galore",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7004,mapID=525,questType="standard"},
[38304] = {id=38304,name="Val'sharah",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7558,mapID=641,description="Go through the portal in Dalaran and meet Malfurion Stormrage in Val'Sharah .",questType="standard"},
[38305] = {id=38305,name="Cenarius, Keeper of the Grove",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7558,mapID=641,description="Greetings, hero. Welcome to Val'sharah . It has been an age since I have set foot in these precious woods. Too long... Our work here is simple. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion. You have many treacherous tasks in front of you. Consider your visit here a brief respite. Come, this will not take long.",questType="standard"},
[38320] = {id=38320,name="Treasure: The Blade of Kra'nak",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38334] = {id=38334,name="Treasure: Jewel of Hellfire",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38341] = {id=38341,name="Halting the Nightmare",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="The corruption of the vale is the work of satyrs. The new power they wield is unlike any I've seen... it is dark, seething and terrible. Nefarious demon totems help spread their taint upon the land. The Nghtmare totems must be destroyed if we are to hold back the tide of corruption.",questType="standard"},
[38353] = {id=38353,name="Rescued From Darkness",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="Midnight Vale is home to a unique breed of Nightsaber known as the Vale Prowler. For centuries, our clan has lived in harmony with these great feline hunters. However, even as we speak satyrs are twisting and corrupting the vale into a place of death and nightmare. Even the forest itself lashes out in torment against the living, causing many of the forest creatures to flee the vale. I fear for the safety of the youngest nightsabers, who may yet be caught in the twisting chaos, unable to escape.",questType="standard"},
[38355] = {id=38355,name="7.0 Val'sharah - Treasure 002 - Moonrest Shore - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
