[38567] = {id=38567,name="Garrison Campaign: War Council",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Your garrison is in an uproar. Warchief Vol'jin himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle. The Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting...",ends={{npcID=92400,x=0.394,y=0.542,mapID=525}},questType="standard"},
[38569] = {id=38569,name="Clearing the Docks",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6721,mapID=543,description="We need to get control of this situation. We thought these docks would be all but abandoned. Instead, Gul'dan has ordered the Iron Horde to retreat to Tanaan, and many are using this harbor to make their getaway. We need to clear a path for your salvage team. Lay waste to them! Every foe we slay here is one less convert for Gul'dan's wretched demon-worshipping army.",questType="standard"},
