[38598] = {id=38598,name="TEST: Craft Some Legplates",level=10,requiredLevel=10,faction="none",expansion=5,description="The Highmountain tauren craft their legplates piece-by-piece, then assemble them all at the end. Seems pretty slow and unnecessarily arduous if you ask me, but we should start here before making any efficiency improvements. Here's some leystone. I've added the recipe into your workbook, as well. Let's give this a shot!",questType="standard"},
