[38607] = {id=38607,name="Gates of Valhallas",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7541,mapID=634,description="Escaping the grasp of Helya is no small feat. You may prove to be a worthy warrior after all. Skovald has entered Valhallas; you are running out of time. Legion has corrupted the minds of the Skovald's men. A battalion of unworthy vrykul is attempting to enter the portal to Valhallas. The giants that protect the gates are fighting a losing battle. There is no end to Legion's onslaught. Speak with the dragon, Vehdir, inside the gates near the portal. He will aid you on your next task.",questType="standard"},
