[38633] = {id=38633,name="Burning Importance",level=40,requiredLevel=40,faction="none",expansion=5,description="Champion, you would not believe the horrors I have seen. The timeline is twisting and your fate is dire. Causality bends at its very knees, and in this dire future you kneel to the Betrayer himself, Illidan Stormrage. Venture into the past and save yourself, but beware - your powers are as they were then.",questType="standard"},
[38637] = {id=38637,name="7.0 Stormheim - Treasure 024 - Haustvald - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38642] = {id=38642,name="Vrykul Longboat",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38648] = {id=38648,name="Black Rook Orders",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7558,mapID=641,description="The letter is written in midnight ink: \"A demon invasion is imminent, but as long as the fires of Black Rook Hold blaze, we shall protect kaldorei lands. Kill any intruders who stand in our way.\" - K.R.\" Perhaps Jarod Shadowsong will want to see this.",questType="standard"},
[38654] = {id=38654,name="Vignette: Giant Raptor",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[38660] = {id=38660,name="Cleansing the Corruption",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="All along the battlefield, the satyrs have erected dark totems that spread the corruption of the Emerald Nightmare upon the land. As long as the Nightmare totems remain, we will not be able to hold back the corruption! If you truly wish to aid us in the fight, destroy the totems that you encounter upon the battlefield. Our survival depends on it!",questType="standard"},
[38661] = {id=38661,name="Nightmare Bombs",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="The satyrs have taken to the skies on giant bats. From the air they rain down the corruption of the nightmare upon us. Disarm the nightmare bombs before they further corrupt the forest.",questType="standard"},
[38668] = {id=38668,name="Our Last Hope",level=1,requiredLevel=1,faction="both",expansion=5,description="Your jailor, Maiev Shadowsong, stands outside the open door to your cell. The leader of the Wardens has just finished removing your bonds. In the distance, you can hear sounds of battle. The unmistakable stench of the Burning Legion wafts through the air.",questType="standard"},
[38669] = {id=38669,name="Our Last Hope",level=8,requiredLevel=8,faction="none",expansion=5,description="The Vault has fallen to the Burning Legion. It pains me to say it, but all is lost, but for one glimmer of hope... YOU. Believe me when I say, I did NOT want to have to do this. However, it would seem I have no choice. Help me, demon hunter, and I will grant you your freedom.",questType="standard"},
[38670] = {id=38670,name="Goredome 2",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38673] = {id=38673,name="The Wormtalon Crone",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="A wicked coven of harpies have overtaken our village. It was the twisting of the forest that forced us out of our village, but now that the harpies have moved in I fear that we may never be able to return. The Wormtalon coven are led by a witch called Grelda the Crone. She has made her nest in a cave near our village. If their leader is defeated, the remaining harpies will surely flee. Slay Grelda the Crone and we will be forever in your debt, .",questType="standard"},
[38676] = {id=38676,name="7.0 Stormheim - Treasure 025 - Weeping Bluffs - ZTO",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38677] = {id=38677,name="7.0 Stormheim - Treasure 026 - Weeping Bluffs - ZTO",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
