[38685] = {id=38685,name="The Nameless King",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38693] = {id=38693,name="[DEPRECATED] Kill Feral Dogs",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="You've done more than enough, . My people and I can clean things up here. You should return to town and report on our victory.",questType="standard"},
[38696] = {id=38696,name="Vignette: Bleeding Hollow Horror",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[38697] = {id=38697,name="The Sword of Truth",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7558,mapID=641,description="Lord Ravencrest's army rises from the dead, but I believe they are controlled by Gul'dan's will. Take this - Lord Ravencrest's blade, Fal'shathil. It was known for a unique, magical quality. Those who gazed upon its mirrored blade found themselves unable to deny the truth. Take the blade and plant it in the ground. Attack the night elven ghosts near its light. Once they are weakened in its presence, perhaps they will regain their senses.",questType="standard"},
[38699] = {id=38699,name="Competitive Exorcise",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7502,mapID=627,description="Think you're good at sending demons back to the hell from whence they came? Show me! I once bagged 15 in under 10 minutes. Do better than that and there'll be brew money waitin' for ya.",questType="standard"},
[38700] = {id=38700,name="Vignette: Steelsnout",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[38707] = {id=38707,name="DEPRECATED",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6723,mapID=534,questType="standard"},
[38708] = {id=38708,name="Purge the River",level=0,requiredLevel=0,faction="none",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38712] = {id=38712,name="Houndmaster Ely",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38726] = {id=38726,name="Vignette: Magwia",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[38737] = {id=38737,name="An End To War",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="It appears that the great Ancient of War, Ironbranch , has fallen to the Nightmare. It pains me greatly to ask this of you, but Ironbranch must be put to rest. In life, he once stood vigil in Shala'nir as a protector of the world tree. In death, my dear friend is no more than a destructive weapon that will be used to cause even more violence. He must be slain before he does more harm to Val'sharah . In my heart, I know that he would thank you for this mercy...",questType="standard"},
[38738] = {id=38738,name="7.0 Stormheim - Treasure 029 - Waterfall - ZTO",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38744] = {id=38744,name="7.0 Stormheim - Treasure 030 - Statue - ZTO",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7541,mapID=634,questType="standard"},
[38745] = {id=38745,name="Hard Lessons",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="Please understand, stranger, that I am a being of peace. I have discarded any vengeful nature long, long ago. In my youth, however, many hard lessons were learned through discipline. When applied wisely and properly, discipline can be a great teacher and shaper of character. It is in the spirit of wisdom and guidance that I would have you teach these harpies a memorable lesson.",questType="standard"},
