[38784] = {id=38784,name="Leystone Seam Sample",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,mapID=627,description="This ore has clearly absorbed some of the latent ley energies within the Broken Isles. It is cool to the touch, and reflects light in odd, playful angles. Your trainer in Dalaran should analyze this.",questType="standard"},
[38785] = {id=38785,name="Living Leystone Sample",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,mapID=627,description="This is no normal leystone. It is much livelier, shimmering in complex, enthralling patterns. It is easy to stare at. Your trainer in Dalaran would certainly like to have a look at this.",questType="standard"},
[38795] = {id=38795,name="Felslate Deposit Sample",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,mapID=627,description="This is one nasty-looking stone. Your trainer in Dalaran should see this.",questType="standard"},
[38796] = {id=38796,name="Felslate Seam Sample",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,mapID=627,description="This ore is remarkably heavy. More disturbingly, it seems to darken and hiss at your touch. Perhaps your mining trainer in Dalaran has some insights.",questType="standard"},
[38797] = {id=38797,name="Living Felslate Sample",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7502,mapID=627,description="Your miner's instinct is kicking in. Chunks of the infernal's corpse appear to be usable. Still, there must be a way to extract more ore from the demon's body. Perhaps your mining trainer in Dalaran will know how.",questType="standard"},
[38806] = {id=38806,name="Infernal Brimstone Sample",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=7502,mapID=627,description="This ore. Smells. Horrible. It combines the odor of sulfur with all the worst parts of a rotting corpse. Someone will probably want it for something. Maybe your mining trainer in Dalaran will take it off of your hands.",questType="standard"},
[38812] = {id=38812,name="Vignette: Shadowthrash",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[38839] = {id=38839,name="Done with Waiting",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=7558,mapID=641,description="Mom got a message and said blood called for blood. She told me to wait here while she went out, but it's been two weeks since then. I'm tired of waiting. I'll stay home if you go find her. She said she was going to the cliffs far to the south.",questType="standard"},
[38840] = {id=38840,name="Fishy Business",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7558,mapID=641,description="Makrura are massing down by the shore, and far too many of them seem to practice water magic. I think once they've got enough spellcasters, they're planning to summon a massive wave.",questType="standard"},
[38856] = {id=38856,name="Holy Retribution",level=1,requiredLevel=1,faction="both",expansion=5,description="I fell in what you now call Tirisfal Glades at the claws of two of Yogg'Saron's most powerful lieutenants... the C'Thraxi. I was able to slay one in my death throes - Az'jtal . Now, the dark forces deep beneath Azeroth have begun to usher Az'jtal once again into this world. You must go to Tyr's Fall and strike Az'jtal down again before it can fully manifest. Only once this deed is done may you receive my blessing upon the Ashbringer.",questType="standard"},
[38861] = {id=38861,name="7.0 Val'sharah - Treasure 019 - Lunarwing Shallows - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
